using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using HabitatIsland;
public static class FinalRouteLab{
 public static HabitatState S;public static List<int[]> R=new List<int[]>();public static Tuning T=new Tuning{animalMovement=false};
 static int[] dx={0,1,0,-1},dz={1,0,-1,0};
 sealed class N{public HabitatState s;public List<int[]> p;}
 static string Key(HabitatState s)=>s.playerX+","+s.playerZ+":"+string.Join(";",s.animals.Select(a=>a.x+","+a.z+","+a.carried))+":"+string.Join(";",s.tiles.Select((v,i)=>new{v,i}).Where(q=>q.v.prop!=PropKind.None).Select(q=>q.i+","+(int)q.v.prop+","+q.v.rotation+","+(int)q.v.coveredProp));
 public static void Begin(int level){S=HabitatLevels.Create(level);S.rod=S.specialRod=S.backBasketUnlocked=true;S.coins=10000;S.chapterOneAccepted=S.chapterOneDelivered=S.chapterOneMorningSeen=true;S.campaignUnlockedStage=level>=5&&level<=8?level-4:5;S.campaignBriefedMask=(1<<(S.campaignUnlockedStage+1))-2;if(level==6)S.backBasketUnlocked=false;R.Clear();if(level==6)S.bagProps.Add(PropKind.Fan);}
 public static void A(params int[] a){bool ok=true;switch(a[0]){
 case 0:ok=HabitatRules.MovePlayer(S,a[1],a[2],true,T);break;case 1:ok=HabitatRules.Interact(S,a[1],a[2]);break;case 2:ok=HabitatRules.Lure(S,a[1],a[2]);break;case 3:ok=HabitatRules.Rotate(S,a[1],a[2]);break;case 4:ok=HabitatRules.StoreHeld(S);break;case 5:ok=HabitatRules.TakeBagProp(S,a[1]);break;case 6:HabitatRules.Tick(S,T,a[1]/10f);break;case 7:ok=HabitatRules.UseUtility(S,a[1],a[2],a[3],a[4],a[5]);break;case 8:ok=HabitatRules.Shop(S,a[1]==7?"launcher":a[1]==6?"magnet":a[1]==5?"shovel":a[1]==3?"fan":"crate");break;case 9:ok=HabitatRules.TransferBoatCrate(S,a[1]!=0);break;case 10:HabitatRules.MovePlayer(S,a[1],a[2],true,T);break;case 11:ok=HabitatRules.PushBox(S,a[1],a[2]);break;case 12:ok=HabitatRules.PullPlayer(S,a[1],a[2]);break;case 13:ok=HabitatRules.RecoverBox(S,a[1],a[2]);break;case 14:S.facingX=a[1];S.facingZ=a[2];break;default:throw new Exception("action");}
 if(!ok)throw new Exception("At action "+R.Count+" ["+string.Join(",",a)+"] "+S.message);R.Add(a);
 }
 public static void W(int x,int z){var q=new Queue<N>();q.Enqueue(new N{s=HabitatRules.Clone(S),p=new List<int[]>()});var seen=new HashSet<string>();while(q.Count>0&&seen.Count<30000){var n=q.Dequeue();if(!seen.Add(Key(n.s)))continue;if(n.s.playerX==x&&n.s.playerZ==z){foreach(var a in n.p)A(a);return;}for(int d=0;d<4;d++){var next=HabitatRules.Clone(n.s);next.events.Clear();if(!HabitatRules.MovePlayer(next,dx[d],dz[d],true,T))continue;
 // Navigation may ride a raft and drive animals, but does not silently push boxes.
 bool boxesChanged=false;for(int k=0;k<next.tiles.Length;k++)if((HabitatRules.IsBox(next.tiles[k].prop)||HabitatRules.IsBox(n.s.tiles[k].prop))&&next.tiles[k].prop!=n.s.tiles[k].prop){boxesChanged=true;break;}if(boxesChanged)continue;
 var path=new List<int[]>(n.p){new[]{0,dx[d],dz[d]}};q.Enqueue(new N{s=next,p=path});}}
 throw new Exception("No walking route to "+x+","+z+" from "+S.playerX+","+S.playerZ+" searched="+seen.Count);}
 public static string Run(int level,string plan){Begin(level);int line=0;try{foreach(string raw in File.ReadAllLines(plan)){line++;string v=raw.Split('#')[0].Trim();if(v.Length==0)continue;var a=v.Split(new[]{' ',','},StringSplitOptions.RemoveEmptyEntries);int[] n=a.Skip(1).Select(int.Parse).ToArray();switch(a[0]){case "D":while(HabitatRules.TileAt(S,n[0],n[1]).rotation%4!=n[2])A(3,n[0],n[1]);break;case "W":W(n[0],n[1]);break;case "I":A(1,n[0],n[1]);break;case "P":A(11,n[0],n[1]);break;case "L":A(2,n[0],n[1]);break;case "R":A(3,n[0],n[1]);break;case "Pull":A(12,n[0],n[1]);break;case "Recover":A(13,n[0],n[1]);break;case "Buy":A(8,n[0],0);break;case "Take":A(5,n[0],0);break;case "Store":A(4,0,0);break;case "Tick":A(6,n[0],0);break;case "Face":A(14,n[0],n[1]);break;case "Cargo":A(9,n[0],0);break;case "U":A(new[]{7}.Concat(n).ToArray());break;case "A":A(n);break;default:throw new Exception(a[0]);}}
 return (HabitatMechanicLevels.CompleteHabitat(S,T)||S.won?"PASS":"INCOMPLETE")+" actions="+R.Count+" cost="+(10000-S.coins);}
 catch(Exception e){return "FAIL line="+line+" "+e.Message;}}
 public static string Dump(){var b=new StringBuilder("P "+S.playerX+","+S.playerZ+" held "+S.carryingProp+"/"+S.carryingAnimal+" tide="+S.waterLevel+"\n");foreach(var a in S.animals)b.AppendLine(a.id+" "+a.species+" "+a.x+","+a.z+" carried="+a.carried+" "+HabitatRules.Evaluate(S,a,T).reason);for(int z=S.depth-1;z>=0;z--){b.Append(z.ToString("D2")+" ");for(int x=0;x<S.width;x++){var p=S.tiles[z*S.width+x];string c=p.height<=0?" .":" "+p.height;if(p.prop!=PropKind.None)c=p.prop==PropKind.Crate?" B":p.prop==PropKind.Float?" F":p.prop==PropKind.Raft?" R":p.prop==PropKind.ClimbBlock?" C":p.prop==PropKind.Obstacle?" #":p.prop==PropKind.Fan?" V":p.prop==PropKind.Chest?" T":p.prop==PropKind.Tide?" ~":" ?";if(S.animals.Any(a=>!a.carried&&a.x==x&&a.z==z))c=" a";if(S.playerX==x&&S.playerZ==z)c=" @";b.Append(c);}b.AppendLine();}b.Append("   ");for(int x=0;x<S.width;x++)b.Append(x.ToString("D2"));return b.ToString();}
}


